// app/api/forms/[id]/submit/route.ts
import { NextResponse } from "next/server";
import { storage } from "@/lib/storage";
import { z } from "zod";

// ✅ Validate that submission data is a non-empty object
const submissionBodySchema = z.record(z.string(), z.unknown()).refine(
  (data) => Object.keys(data).length > 0,
  { message: "Submission data cannot be empty" }
);

export async function POST(
  request: Request,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await context.params;
    const formId = Number(id);

    if (Number.isNaN(formId)) {
      return NextResponse.json({ error: "Invalid form ID" }, { status: 400 });
    }

    // Verify form exists
    const form = await storage.getForm(formId);
    if (!form) {
      return NextResponse.json({ error: "Form not found" }, { status: 404 });
    }

    // ✅ Fix: check if form is published before accepting submissions
    if (!form.isPublished) {
      return NextResponse.json(
        { error: "This form is not accepting submissions" },
        { status: 403 }
      );
    }

    const body = await request.json();

    // ✅ Fix: validate the body is a proper non-empty object
    const parsedBody = submissionBodySchema.safeParse(body);
    if (!parsedBody.success) {
      return NextResponse.json(
        {
          error: "Validation error",
          details: parsedBody.error.flatten().fieldErrors,
        },
        { status: 400 }
      );
    }

    const submission = await storage.createSubmission({
      formId,
      data: parsedBody.data,
    });

    return NextResponse.json(submission, { status: 201 });
  } catch (error) {
    console.error("Error creating submission:", error);
    return NextResponse.json(
      { error: "Failed to create submission" },
      { status: 500 }
    );
  }
}

import { db } from "./db";
import {
  forms,
  submissions,
  type InsertForm,
  type Form,
  type InsertSubmission,
  type Submission,
  type UpdateFormRequest,
  Faculty,
  CreateFacultyRequest,
  UpdateFacultyRequest,
  Post,
  CreatePostRequest,
  UpdatePostRequest,
  faculty,
  posts
} from "@/shared/schema";
import { eq, asc, desc } from "drizzle-orm";

import { galleryImages, type GalleryImage, type InsertGalleryImage, type GalleryCategory } from "@/shared/schema";

export interface IStorage {
  getForms(): Promise<Form[]>;
  getForm(id: number): Promise<Form | undefined>;
  createForm(form: InsertForm): Promise<Form>;
  updateForm(id: number, updates: UpdateFormRequest): Promise<Form>;
  createSubmission(submission: InsertSubmission): Promise<Submission>;
  getSubmissions(formId: number): Promise<Submission[]>;
  deleteForm(id: number): Promise<void>;
  // Faculty
  getFacultyList(): Promise<Faculty[]>;
  getFaculty(id: number): Promise<Faculty | undefined>;
  createFaculty(faculty: CreateFacultyRequest): Promise<Faculty>;
  updateFaculty(id: number, updates: UpdateFacultyRequest): Promise<Faculty>;
  deleteFaculty(id: number): Promise<void>;

  // Posts
  getPosts(category?: "blog" | "announcement" | "notice"): Promise<Post[]>;
  getPost(id: number): Promise<Post | undefined>;
  createPost(post: CreatePostRequest): Promise<Post>;
  updatePost(id: number, updates: UpdatePostRequest): Promise<Post>;
  deletePost(id: number): Promise<void>;

  getGalleryImages(category?: GalleryCategory): Promise<GalleryImage[]>;
  getGalleryImage(id: number): Promise<GalleryImage | undefined>;
  createGalleryImage(image: InsertGalleryImage): Promise<GalleryImage>;
  updateGalleryImage(id: number, updates: Partial<InsertGalleryImage>): Promise<GalleryImage | undefined>;
  deleteGalleryImage(id: number): Promise<void>;
  reorderGalleryImages(order: { id: number; displayOrder: number }[]): Promise<void>;
}

export class DatabaseStorage implements IStorage {
  async getForms(): Promise<Form[]> {
    return await db.select().from(forms).orderBy(desc(forms.createdAt));
  }

  async getForm(id: number): Promise<Form | undefined> {
    const [form] = await db.select().from(forms).where(eq(forms.id, id));
    return form;
  }

  async createForm(insertForm: InsertForm): Promise<Form> {
    const [form] = await db.insert(forms).values(insertForm).returning();
    return form;
  }

  async updateForm(id: number, updates: UpdateFormRequest): Promise<Form> {
    const [updated] = await db
      .update(forms)
      .set(updates)
      .where(eq(forms.id, id))
      .returning();
    return updated;
  }

  async createSubmission(insertSubmission: InsertSubmission): Promise<Submission> {
    const [submission] = await db
      .insert(submissions)
      .values(insertSubmission)
      .returning();
    return submission;
  }

  async getSubmissions(formId: number): Promise<Submission[]> {
    return await db
      .select()
      .from(submissions)
      .where(eq(submissions.formId, formId))
      .orderBy(desc(submissions.submittedAt));
  }

  async deleteForm(id: number): Promise<void> {
    await db.delete(forms).where(eq(forms.id, id));
  }

  // Faculty Operations
  async getFacultyList(): Promise<Faculty[]> {
    return await db.select().from(faculty);
  }

  async getFaculty(id: number): Promise<Faculty | undefined> {
    const [item] = await db.select().from(faculty).where(eq(faculty.id, id));
    return item;
  }

  async createFaculty(insertFaculty: CreateFacultyRequest): Promise<Faculty> {
    const [item] = await db.insert(faculty).values(insertFaculty).returning();
    return item;
  }

  async updateFaculty(id: number, updates: UpdateFacultyRequest): Promise<Faculty> {
    const [item] = await db.update(faculty)
      .set(updates)
      .where(eq(faculty.id, id))
      .returning();
    return item;
  }

  async deleteFaculty(id: number): Promise<void> {
    await db.delete(faculty).where(eq(faculty.id, id));
  }

  // Post Operations
  async getPosts(category?: "blog" | "announcement" | "notice"): Promise<Post[]> {
    if (category) {
      return await db.select().from(posts).where(eq(posts.category, category)).orderBy(desc(posts.createdAt));
    }
    return await db.select().from(posts).orderBy(desc(posts.createdAt));
  }

  async getPost(id: number): Promise<Post | undefined> {
    const [item] = await db.select().from(posts).where(eq(posts.id, id));
    return item;
  }

  async createPost(insertPost: CreatePostRequest): Promise<Post> {
    const [item] = await db.insert(posts).values(insertPost).returning();
    return item;
  }

  async updatePost(id: number, updates: UpdatePostRequest): Promise<Post> {
    const [item] = await db.update(posts)
      .set(updates)
      .where(eq(posts.id, id))
      .returning();
    return item;
  }

  async deletePost(id: number): Promise<void> {
    await db.delete(posts).where(eq(posts.id, id));
  }

  async getGalleryImages(category?: GalleryCategory): Promise<GalleryImage[]> {
    if (category && category !== "all") {
      return await db
        .select()
        .from(galleryImages)
        .where(eq(galleryImages.category, category))
        .orderBy(asc(galleryImages.displayOrder));
    }
    return await db.select().from(galleryImages).orderBy(asc(galleryImages.displayOrder));
  }

  async getGalleryImage(id: number): Promise<GalleryImage | undefined> {
    const [image] = await db.select().from(galleryImages).where(eq(galleryImages.id, id));
    return image;
  }

  async createGalleryImage(image: InsertGalleryImage): Promise<GalleryImage> {
    const [created] = await db.insert(galleryImages).values(image).returning();
    return created;
  }

  async updateGalleryImage(id: number, updates: Partial<InsertGalleryImage>): Promise<GalleryImage | undefined> {
    const [updated] = await db
      .update(galleryImages)
      .set(updates)
      .where(eq(galleryImages.id, id))
      .returning();
    return updated;
  }

  async deleteGalleryImage(id: number): Promise<void> {
    await db.delete(galleryImages).where(eq(galleryImages.id, id));
  }

  async reorderGalleryImages(order: { id: number; displayOrder: number }[]): Promise<void> {
    // Drizzle doesn't support bulk update natively — run in parallel
    await Promise.all(
      order.map(({ id, displayOrder }) =>
        db.update(galleryImages).set({ displayOrder }).where(eq(galleryImages.id, id))
      )
    );
  }
}

